def count_binary_k_constraint_substrings(s,k):
    answer=0
    for left in range(len(s)):
        zeros=ones=0
        for right in range(left,len(s)):
            zeros+=s[right]=='0';ones+=s[right]=='1'
            if zeros<=k or ones<=k:answer+=1
    return answer

